/** @var array{total: int, compliant: int, non_compliant: int, percentage: float|null, latest: array<string, mixed>|null} $summary */
$months = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];
$periodLabel = $report['periods'][$report['default_period']];
$latest = $summary['latest'];
